def decide(trace):
    # The required phase-specific values and ordering for the declared
    # outputs are not defined by the supplied specification.  sda_chk is
    # internal and is not present in the declared trace ports.
    observed = any(
        'scl_oen' in row.get('outputs', {}) or
        'sda_oen' in row.get('outputs', {})
        for row in trace
    )
    if not observed:
        return (None, None, 'scl_oen and sda_oen were not observable in this trace')
    return (None, None, 'phase-specific scl_oen/sda_oen behavior is not defined by the supplied specification')

def decide(trace):
    # `busy` is the only declared output route supplied for this requirement.
    # Its value alone cannot identify the internal idle-state activation or
    # distinguish an unsupported command from an unexercised command case.
    busy_observed = [r for r in trace if 'busy' in r.get('outputs', {})]
    if not busy_observed:
        return (None, None, 'busy was not present in the declared trace outputs')
    return (None, None, 'cannot identify the internal idle-state activation or command symbols from declared ports; busy is the only observable route')

def decide(trace):
    saw_low = False
    for row in trace:
        outputs = row['outputs']
        scl_oen = outputs['scl_oen']
        sda_oen = outputs['sda_oen']

        if scl_oen == 0:
            saw_low = True
            if outputs['scl_o'] != 0:
                return (False, row['edge'],
                        'scl_oen is low but scl_o is not 0; the SCL line is not driven low')

        if sda_oen == 0:
            saw_low = True
            if outputs['sda_o'] != 0:
                return (False, row['edge'],
                        'sda_oen is low but sda_o is not 0; the SDA line is not driven low')

    if not saw_low:
        return (None, None,
                'neither output enable was observed low; the pulled-low case was not exercised')

    return (True, None,
            'whenever scl_oen or sda_oen was low, the corresponding line-drive output was 0; high enable denotes release')

from specflow.refmodel.temporal import WHILE_ACTIVE, after, throughout, worst

def decide(trace):
    def active(row):
        return (
            row['outputs'].get('busy') == 1
            and row['outputs'].get('sda_oen') == 1
            and row['inputs'].get('sda_i') == 0
        )

    def aborted(row):
        return (
            row['inputs'].get('nReset') == 0
            or row['inputs'].get('rst') == 1
        )

    windows = after(trace, active, until=WHILE_ACTIVE, aborts=aborted)
    return worst([
        throughout(
            window,
            lambda row: row['outputs'].get('al') == 1,
            after_activation=False
        )
        for window in windows
    ])

def decide(trace):
    active_transitions = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        prev_scl = prev['outputs'].get('scl_oen')
        scl = row['outputs'].get('scl_oen')
        if prev_scl is None or scl is None:
            continue
        if prev_scl != scl and row['outputs'].get('busy') == 1:
            active_transitions.append(i)

    if len(active_transitions) < 2:
        return (None, None, 'scl_oen has fewer than two phase transitions during an active command sequence')

    for previous, current in zip(active_transitions, active_transitions[1:]):
        elapsed = sum(trace[k].get('held', 1) for k in range(previous, current))
        configured = trace[previous]['inputs'].get('clk_cnt')
        if configured is None:
            return (None, None, 'clk_cnt is unavailable at the phase boundary')
        if elapsed not in (configured, configured + 1):
            return (False, trace[current]['edge'],
                    f'scl_oen phase transition interval was {elapsed} edges, not the clk_cnt-derived interval from clk_cnt={configured}')

    return (True, trace[active_transitions[-1]]['edge'],
            'successive active scl_oen phase transitions follow the clk_cnt-derived timing interval')

def decide(trace):
    # No cmd encoding is declared, so use the declared completion signature:
    # busy falling to idle while enabled and out of reset.
    completion_edges = set()
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        if (prev['outputs'].get('busy') == 1 and
                row['outputs'].get('busy') == 0 and
                row['inputs'].get('ena') == 1 and
                row['inputs'].get('nReset') == 1 and
                row['inputs'].get('rst') == 0):
            completion_edges.add(row['edge'])

    if not completion_edges:
        return (None, None,
                'no enabled, non-reset command-completion edge was witnessed')

    for i, row in enumerate(trace):
        if row['edge'] not in completion_edges:
            continue

        ack = row['outputs'].get('cmd_ack')
        if ack != 1:
            return (False, row['edge'],
                    "cmd_ack was not asserted when the command finished; expected one clk-cycle acknowledge")

        if i > 0 and trace[i - 1]['outputs'].get('cmd_ack') == 1:
            return (False, row['edge'],
                    'cmd_ack was already asserted before command completion')

        held_edges = 0
        j = i
        while j < len(trace) and trace[j]['outputs'].get('cmd_ack') == 1:
            held_edges += trace[j].get('held', 1)
            j += 1

        if j == len(trace):
            return (None, row['edge'],
                    'cmd_ack was asserted at completion, but the trace ended before its one-cycle duration was bounded')

        if held_edges != 1:
            return (False, row['edge'],
                    f"cmd_ack was asserted for {held_edges} edges, expected exactly one clk cycle")

    return (True, min(completion_edges),
            'cmd_ack was asserted for exactly one clk cycle at each witnessed command completion')

def decide(trace):
    observable = ('al', 'busy', 'cmd_ack', 'scl_oen', 'sda_oen')
    reset_rows = [
        (i, row) for i, row in enumerate(trace)
        if row.get('inputs', {}).get('rst') == 1
    ]

    if not reset_rows:
        return (None, None, 'synchronous rst assertion never occurred')

    # The reset values are unspecified by this requirement.  Use the first
    # reset-state observation as the reset-state reference, without importing
    # values from the neighbouring reset-behaviour requirement.
    first_i, first_row = reset_rows[0]
    reference = {
        port: first_row.get('outputs', {}).get(port)
        for port in observable
    }

    if len(reset_rows) == 1:
        return (None, first_row.get('edge'),
                'rst was asserted, but the trace contains no later reset state with which to check stability')

    for i, row in reset_rows[1:]:
        outputs = row.get('outputs', {})
        changed = [
            (port, reference[port], outputs.get(port))
            for port in observable
            if outputs.get(port) != reference[port]
        ]
        if changed:
            port, expected, actual = changed[0]
            return (
                False,
                row.get('edge'),
                f'while rst remained high, observable reset state changed on {port}: '
                f'{expected!r} to {actual!r}'
            )

    return (
        True,
        None,
        'observable reset state remained stable for all distinct states while rst was high; '
        'no reset encoding was assumed'
    )

def decide(trace):
    previous = None
    first_change_edge = None
    for row in trace:
        value = row.get('outputs', {}).get('scl_oen')
        if previous is not None and value != previous and first_change_edge is None:
            first_change_edge = row.get('edge')
        previous = value
    if first_change_edge is None:
        return (None, None, 'clk_en and the FSM state are internal; no observable scl_oen phase transition was found')
    return (None, first_change_edge, 'scl_oen changed, but the declared trace does not expose clk_en, so the cause of the FSM advance is undecidable')

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, worst

    def output(row, port):
        return row.get('outputs', {}).get(port)

    scl_i_falls = edges(trace, 'scl_i', 'fall')
    scl_oen_falls = edges(trace, 'scl_oen', 'fall')
    scl_oen_rises = edges(trace, 'scl_oen', 'rise')

    # The alternate route case: an ordinary released-high interval in which
    # no external SCL falling edge occurs before scl_oen returns low.
    ordinary_completion = False
    released_start = None
    for row in trace:
        edge = row['edge']
        if edge in scl_oen_rises:
            released_start = edge
        elif edge in scl_oen_falls:
            start = released_start if released_start is not None else -1
            if not any(start < fall < edge for fall in scl_i_falls):
                ordinary_completion = True
                break

    if not ordinary_completion:
        return (None, None,
                'ordinary released-high completion without an external scl_i fall was not observed; the route shows only one case')

    # Shared-SCL-low condition in the released-high WRITE-bit signature.
    # This is deliberately level-based so an already-low scl_i is covered.
    windows = after(
        trace,
        lambda r: r.get('inputs', {}).get('scl_i') == 0
                  and output(r, 'scl_oen') == 1,
        until=TO_END
    )

    if not windows:
        return (None, None,
                'shared SCL low during the released-high phase was not observed')

    return worst([
        eventually(
            window,
            lambda r: r['edge'] in scl_oen_falls,
            strong=False,
            after_activation=False
        )
        for window in windows
    ])

from specflow.refmodel.temporal import TO_END, after, never, throughout, worst

def decide(trace):
    # No command encoding table is specified.  Use only command symbols whose
    # values are demonstrated by normal command activity while ena is high.
    valid_cmds = {
        r['inputs'].get('cmd')
        for r in trace
        if r['inputs'].get('ena') == 1
        and (r['outputs'].get('busy') == 1 or r['outputs'].get('cmd_ack') == 1)
    }
    valid_cmds.discard(None)
    if not valid_cmds:
        return (None, None, 'no valid command value was demonstrated with ena high')

    verdicts = []
    for cmd_value in valid_cmds:
        # Route condition: FSM idle (busy low), a valid command is held, and
        # ena is low.  The window ends when the held-input situation ends, not
        # when busy changes, so an erroneous busy assertion remains observable.
        applies = lambda r, v=cmd_value: (
            r['inputs'].get('ena') == 0
            and r['inputs'].get('cmd') == v
            and r['outputs'].get('busy') == 0
        )
        stops = lambda r, v=cmd_value: (
            r['inputs'].get('ena') != 0
            or r['inputs'].get('cmd') != v
        )
        windows = after(trace, applies, until=stops)

        for w in windows:
            verdicts.append(
                throughout(
                    w,
                    lambda r: r['outputs'].get('busy') == 0,
                    after_activation=False,
                )
            )
            verdicts.append(
                never(
                    w,
                    lambda r: r['outputs'].get('cmd_ack') == 1,
                    after_activation=False,
                )
            )

    return worst(verdicts)

def decide(trace):
    from specflow.refmodel.temporal import WHILE_ACTIVE, after, throughout, worst

    def async_reset(row):
        return row['inputs'].get('nReset') == 0

    def sync_reset(row):
        return row['inputs'].get('rst') == 1

    def reset_outputs(row):
        outputs = row['outputs']
        return (
            outputs.get('scl_oen') == 1 and
            outputs.get('sda_oen') == 1 and
            outputs.get('cmd_ack') == 0 and
            outputs.get('al') == 0 and
            outputs.get('busy') == 0
        )

    async_windows = after(trace, async_reset, until=WHILE_ACTIVE)
    sync_windows = after(trace, sync_reset, until=WHILE_ACTIVE)

    verdicts = [
        throughout(window, reset_outputs, after_activation=False)
        for window in async_windows
    ]
    verdicts.extend(
        throughout(window, reset_outputs, after_activation=True)
        for window in sync_windows
    )
    return worst(verdicts)

def decide(trace):
    # `clk_en` is internal and has no declared trace port.  The command
    # encoding is also unspecified, so no numeric command trigger is used.
    # Observe only the routed phase indication: changes of scl_oen while the
    # module is enabled and out of reset.  A stable value between such changes
    # is the routed ordinary behaviour, not this requirement's effect.
    eligible = [
        r for r in trace
        if r['inputs'].get('ena') == 1
        and r['inputs'].get('nReset') != 0
        and r['inputs'].get('rst') != 1
    ]
    changes = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        if row['outputs'].get('scl_oen') != prev['outputs'].get('scl_oen'):
            if row in eligible:
                changes.append(row)

    if not eligible:
        return (None, None, 'no enabled, non-reset transaction was observed')
    if not changes:
        return (None, eligible[-1].get('edge'),
                'no routed scl_oen phase advancement was observed; internal clk_en is not declared')

    return (True, changes[0].get('edge'),
            f'{len(changes)} routed scl_oen phase advancement(s) observed while enabled and out of reset; clk_en is internal and not directly observable')

def decide(trace):
    from specflow.refmodel.temporal import WHILE_ACTIVE, after, eventually, worst

    def applies(row):
        return (
            row['inputs'].get('ena') == 1
            and row['inputs'].get('nReset') == 1
            and row['inputs'].get('rst') == 0
            and row['inputs'].get('sda_i') == 0
            and row['outputs'].get('scl_oen') == 1
            and row['outputs'].get('sda_oen') == 1
        )

    def aborts(row):
        return (
            row['inputs'].get('nReset') == 0
            or row['inputs'].get('rst') == 1
        )

    windows = after(trace, applies, until=WHILE_ACTIVE, aborts=aborts)
    return worst([
        eventually(
            w,
            lambda r: r['outputs'].get('al') == 1,
            strong=True,
            after_activation=False,
        )
        for w in windows
    ])

def decide(trace):
    # cmd_ack is the declared observable route, but samples at rising
    # edges cannot reveal updates between those edges.
    sampled_cmd_ack = [row['outputs'].get('cmd_ack') for row in trace]
    return (None, None, 'cmd_ack is sampled only at rising-edge states; the trace cannot establish whether synchronous updates occur exclusively on rising edges of clk')

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, throughout, worst

    start_edges = edges(trace, "sda_i", "fall")
    stop_edges = edges(trace, "sda_i", "rise")

    def not_reset(row):
        return row["inputs"].get("nReset") != 0 and row["inputs"].get("rst") != 1

    def start(row):
        return (
            row["edge"] in start_edges
            and row["inputs"].get("scl_i") == 1
            and not_reset(row)
        )

    def stop(row):
        return (
            row["edge"] in stop_edges
            and row["inputs"].get("scl_i") == 1
            and not_reset(row)
        )

    def reset(row):
        return row["inputs"].get("nReset") == 0 or row["inputs"].get("rst") == 1

    start_windows = after(
        trace,
        start,
        until=stop,
        aborts=reset,
    )
    busy_during_transaction = [
        throughout(
            window,
            lambda row: row["outputs"].get("busy") == 1,
            after_activation=True,
        )
        for window in start_windows
    ]

    stop_windows = after(
        trace,
        stop,
        until=TO_END,
        aborts=reset,
    )
    busy_clears_after_stop = [
        eventually(
            window,
            lambda row: row["outputs"].get("busy") == 0,
            strong=True,
            after_activation=True,
        )
        for window in stop_windows
    ]

    return worst(busy_during_transaction + busy_clears_after_stop)

