from specflow.refmodel.temporal import TO_END, after, edges, eventually, worst

def decide(trace):
    fell = edges(trace, "scl_i", "fall")

    def applies(row):
        return (row["edge"] in fell
                and row["outputs"].get("scl_oen") == 1
                and row["outputs"].get("busy") == 1)

    windows = after(trace, applies, until=TO_END)
    if not windows:
        return (None, None, "no falling edge on scl_i while scl_oen was released during an active sequence")

    verdicts = []
    for w in windows:
        first = w.rows[0]
        if first["outputs"].get("cmd_ack") != 0:
            verdicts.append((False, first["edge"], "cmd_ack was not postponed at the SCL synchronization event"))
            continue

        later_ack = eventually(
            w,
            lambda r: r["outputs"].get("cmd_ack") == 1,
            after_activation=True,
            strong=False,
        )
        verdicts.append(later_ack)

    result = worst(verdicts)
    if result[0] is None:
        return (None, result[1], "the SCL synchronization event was seen, but the postponed completion indication was not observed before the trace ended")
    return result

