def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, throughout, worst

    scl_changes = edges(trace, "scl_oen", "change")
    sda_changes = edges(trace, "sda_oen", "change")
    starts = scl_changes | sda_changes

    def not_in_reset(row):
        return row["inputs"].get("nReset") != 0 and row["inputs"].get("rst") != 1

    def opens(row):
        return row["edge"] in starts and not_in_reset(row)

    def reset(row):
        return row["inputs"].get("nReset") == 0 or row["inputs"].get("rst") == 1

    windows = after(trace, opens, until=TO_END, aborts=reset)
    return worst([
        throughout(
            w,
            lambda r: r["outputs"].get("scl_o") == 0 and
                      r["outputs"].get("sda_o") == 0,
            after_activation=False
        )
        for w in windows
    ])

