def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    def reset_active(row):
        return inp(row, 'nReset') == 0 or inp(row, 'rst') == 1

    def changed_to(i, port, value):
        if i <= 0:
            return False
        return out(trace[i], port) != value and out(trace[i - 1], port) == value

    # With no command encoding table, use the declared STOP-shaped output
    # signature as the activation. ena is an input qualification only.
    candidates = []
    for i, row in enumerate(trace):
        if inp(row, 'ena') == 1 and i > 0:
            if out(trace[i - 1], 'sda_oen') != 0 and out(row, 'sda_oen') == 0:
                candidates.append(i)

    if not candidates:
        return (None, None,
                'STOP command encoding is unspecified and no STOP-shaped SDA drive was observed')

    for start in candidates:
        if reset_active(trace[start]):
            continue

        scl_release = None
        sda_release = None
        ack = None
        aborted = False

        for i in range(start + 1, len(trace)):
            if reset_active(trace[i]):
                aborted = True
                break

            if scl_release is None:
                if changed_to(i, 'scl_oen', 1):
                    scl_release = i
                continue

            if sda_release is None:
                if changed_to(i, 'sda_oen', 1) and out(trace[i], 'scl_oen') == 1:
                    sda_release = i
                continue

            if changed_to(i, 'cmd_ack', 1):
                ack = i
                break

        if aborted:
            continue

        if scl_release is None:
            return (False, trace[start]['edge'],
                    'STOP signature began with sda_oen driven low, but scl_oen was not subsequently released high')

        if sda_release is None:
            return (False, trace[scl_release]['edge'],
                    'SCL was released, but sda_oen was not subsequently released high while scl_oen was high')

        if ack is None:
            return (False, trace[sda_release]['edge'],
                    'STOP sequence completed, but cmd_ack was not subsequently asserted')

        return (True, trace[ack]['edge'],
                'STOP sequence observed in order: SDA driven low, SCL released high, SDA released high while SCL was high, then cmd_ack asserted')

    return (None, None, 'the observable STOP attempt was aborted by reset')

