from specflow.refmodel.temporal import TO_END, after, edges, throughout

def decide(trace):
    sda_rise = edges(trace, "sda_i", "rise")
    sda_fall = edges(trace, "sda_i", "fall")
    scl_release = edges(trace, "scl_oen", "rise")
    scl_fall = edges(trace, "scl_oen", "fall")
    scl_low_fall = edges(trace, "scl_i", "fall")
    scl_high = edges(trace, "scl_i", "rise")

    bus_events = []
    for i, row in enumerate(trace):
        if row["inputs"].get("scl_i") != 1:
            continue
        if row["edge"] in sda_rise or row["edge"] in sda_fall:
            bus_events.append(i)

    if not bus_events:
        return (None, None, "no START or STOP bus-status transition occurred while scl_i was high")

    wait_verdicts = []
    ordinary_seen = False

    for start in bus_events:
        suffix = trace[start:]
        wait_rows = set()
        for row in suffix:
            e = row["edge"]
            if (e in scl_release and row["inputs"].get("scl_i") == 0) or \
               (e in scl_low_fall and row["outputs"].get("scl_oen") == 1):
                wait_rows.add(e)

        def opens_wait(row):
            e = row["edge"]
            return e in wait_rows

        windows = after(
            suffix,
            opens_wait,
            until=lambda r: r["inputs"].get("scl_i") == 1
        )
        wait_verdicts.extend(
            throughout(
                w,
                lambda r: r["outputs"].get("scl_oen") == 1,
                after_activation=False
            )
            for w in windows
        )

        for row in suffix[1:]:
            if row["edge"] in scl_fall:
                ordinary_seen = True
                break

    if not wait_verdicts:
        return (None, None, "bus-status detection occurred, but no declared SCL-stretch or synchronization condition was exercised")

    for verdict in wait_verdicts:
        if verdict[0] is False:
            return verdict
    if any(verdict[0] is None for verdict in wait_verdicts):
        return (None, None, "the SCL wait window was not completely observed before the trace ended")
    if not ordinary_seen:
        return (None, None, "the trace showed the wait-side scl_oen behaviour but no contrasting ordinary scl_oen transition")

    return (True, None, "after bus-status detection, scl_oen remained released throughout the observed SCL-low wait and ordinary scl_oen behaviour was also observed")

