    from specflow.refmodel.temporal import after

    def any_condition(conditions):
        def predicate(row):
            return any(all(row['outputs'].get(k, row['inputs'].get(k)) == v
                           for k, v in condition.items())
                       for condition in conditions)
        return predicate

    command_changes = {
        row['edge']
        for i, row in enumerate(trace)
        if i > 0
        and row['inputs'].get('cmd') != trace[i - 1]['inputs'].get('cmd')
    }
    scl_releases = {
        row['edge']
        for i, row in enumerate(trace)
        if i > 0
        and row['outputs'].get('scl_oen') == 1
        and trace[i - 1]['outputs'].get('scl_oen') != 1
    }
    scl_pulls_low = {
        row['edge']
        for i, row in enumerate(trace)
        if i > 0
        and row['outputs'].get('scl_oen') == 0
        and trace[i - 1]['outputs'].get('scl_oen') != 0
    }
    ack_rises = {
        row['edge']
        for i, row in enumerate(trace)
        if i > 0
        and row['outputs'].get('cmd_ack') == 1
        and trace[i - 1]['outputs'].get('cmd_ack') != 1
    }
    ack_falls = {
        row['edge']
        for i, row in enumerate(trace)
        if i > 0
        and row['outputs'].get('cmd_ack') == 0
        and trace[i - 1]['outputs'].get('cmd_ack') != 0
    }

