        trace,
        opens,
        until=lambda row: row['outputs'].get('cmd_ack') == 1,
        aborts=aborts,
    )

    if not windows:
        return (None, None, 'the WRITE activation never occurred')

    results = []
    for window in windows:
        rows = window.rows
        release = next((r for r in rows if r['edge'] in scl_releases), None)
        if release is None:
            results.append((False, window.edge,
                            'SCL was not released high during the command sequence'))
            continue

        pull_low = next((r for r in rows
                         if r['index'] > release['index']
                         and r['edge'] in scl_pulls_low), None)
        if pull_low is None:
            results.append((False, release['edge'],
                            'SCL was not driven low after its release'))
            continue

