            return (False, row['edge'],
                    f'cmd_ack for a command-sequence completion was asserted for {duration} clk edge(s), expected exactly one')

        if j == len(trace):
            unknown = True
            continue

        checked += 1

    if unknown and checked == 0:
        return (None, trace[completions[-1]]['edge'],
                'the command-completion observation was aborted or the cmd_ack pulse was still open at trace end')
    if unknown:
        return (None, trace[completions[-1]]['edge'],
                'some command-completion observations were incomplete or aborted')

    return (True, trace[completions[-1]]['edge'],
            f'{checked} command-sequence completion(s), each with a one-clk cmd_ack assertion')

